// SPDX-License-Identifier: Apache-2.0
// Matched userspace network control: same page ABI and resident GPU dispatcher.
#include <sys/epoll.h>
#include <sys/uio.h>
#include <sys/eventfd.h>
#include <cerrno>
#include <cstring>
#include <map>
#include <deque>
#include <memory>
#include <string>
#include <chrono>

static volatile sig_atomic_t user_wake_fd=-1;
static void user_network_interrupt() {
    int fd=user_wake_fd;
    if(fd>=0) { uint64_t one=1;ssize_t ignored=write(fd,&one,sizeof(one));(void)ignored; }
}

static int user_network(bf_page *page,int listener,unsigned seconds,
                        volatile sig_atomic_t *stopped) {
    struct Peer {
        int fd;
        bool eof=false,queued=false;
        int slot=-1;
        std::string input;
    };
    struct Pending {
        std::shared_ptr<Peer> peer;
        size_t offset,bytes;
        unsigned prompt,gen;
        unsigned long long client_ns;
        bool http;
    };
    std::deque<Pending> pending;
    size_t queued_peak=0;
    struct Reply {
        std::shared_ptr<Peer> peer;
        std::string header;
        size_t header_sent=0,bytes=0;
    } replies[BF_LLM_SLOTS];
    std::map<int,std::shared_ptr<Peer>> peers;
    unsigned head=0,completed=0,rejected_count=0,accepted=0;
    int ep=epoll_create1(EPOLL_CLOEXEC);
    if(ep<0) { perror("epoll_create1");return 1; }
    fcntl(listener,F_SETFL,fcntl(listener,F_GETFL)|O_NONBLOCK);
    epoll_event watch={};watch.events=EPOLLIN;watch.data.fd=listener;
    if(epoll_ctl(ep,EPOLL_CTL_ADD,listener,&watch)) { close(ep);return 1; }
    int wake=eventfd(0,EFD_NONBLOCK|EFD_CLOEXEC);
    if(wake<0) { close(ep);return 1; }
    watch.events=EPOLLIN;watch.data.fd=wake;
    if(epoll_ctl(ep,EPOLL_CTL_ADD,wake,&watch)) { close(wake);close(ep);return 1; }
    user_wake_fd=wake;
    auto disconnect=[&](Peer &peer) {
        if(peer.fd>=0) {
            epoll_ctl(ep,EPOLL_CTL_DEL,peer.fd,nullptr);
            close(peer.fd);peer.fd=-1;
        }
        peer.eof=true;
    };
    // Queue each complete eligible frame once, when readiness is observed.
    // A connection retains its existing one-in-flight response-order contract.
    auto enqueue=[&](const std::shared_ptr<Peer> &peer) {
        if(peer->fd<0 || peer->slot>=0 || peer->queued || peer->input.empty())return;
        size_t offset=0;
        bool http=peer->input.compare(0,4,"POST")==0;
        if(http) {
            size_t end=peer->input.find("\r\n\r\n");
            if(end==std::string::npos)return;
            offset=end+4;
        }
        if(peer->input.size()<offset+24)return;
        unsigned fields[4];unsigned long long client_ns;
        memcpy(fields,peer->input.data()+offset,16);
        memcpy(&client_ns,peer->input.data()+offset+16,8);
        unsigned prompt=fields[1],gen=fields[2];
        if(fields[0]!=BF_LLM_MAGIC || !prompt || prompt>BF_LLM_MAX_TOK ||
           !gen || gen>BF_LLM_MAX_TOK) { disconnect(*peer);return; }
        size_t bytes=24+prompt*4;
        if(http) {
            size_t key=peer->input.find("\r\nContent-Length: ");
            if(key==std::string::npos || key>=offset ||
               strtoul(peer->input.c_str()+key+18,nullptr,10)!=bytes) {
                disconnect(*peer);return;
            }
        }
        if(peer->input.size()<offset+bytes)return;
        pending.push_back({peer,offset,bytes,prompt,gen,client_ns,http});
        peer->queued=true;
        if(pending.size()>queued_peak)queued_peak=pending.size();
    };
    auto send_reply=[&](Peer &peer,Reply &reply,bf_llm_slot *slot,unsigned produced) {
        iovec vec[2];unsigned count=0;
        size_t header_bytes=reply.header.size()-reply.header_sent;
        if(header_bytes) vec[count++]={reply.header.data()+reply.header_sent,header_bytes};
        if(produced*4>reply.bytes)
            vec[count++]={(char *)slot->tok_out+reply.bytes,produced*4-reply.bytes};
        if(!count) return;
        msghdr msg={};msg.msg_iov=vec;msg.msg_iovlen=count;
        ssize_t n=sendmsg(peer.fd,&msg,MSG_DONTWAIT|MSG_NOSIGNAL);
        if(n<0 && errno!=EAGAIN && errno!=EWOULDBLOCK && errno!=EINTR)
            disconnect(peer);
        if(n>0) {
            size_t sent_header=(size_t)n<header_bytes ? (size_t)n : header_bytes;
            reply.header_sent+=sent_header;reply.bytes+=(size_t)n-sent_header;
        }
    };
#ifdef BF_USER_NETWORK_WAIT
    printf("userspace completion wait=epoll_pwait2 active_timeout_ns=60000 idle=socket_or_deadline shutdown=eventfd\n");
#else
    printf("userspace completion wait=busy epoll_wait timeout_ms=0\n");
#endif
    fflush(stdout);
    auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(seconds);
    while(!*stopped && std::chrono::steady_clock::now()<deadline) {
        epoll_event events[BF_LLM_SLOTS*2];
#ifdef BF_USER_NETWORK_WAIT
        // Socket readiness wakes immediately; GPU completions are polled after
        // the same nominal 60 us lower wait bound used by kernel TX.
        auto remaining=std::chrono::duration_cast<std::chrono::nanoseconds>(
            deadline-std::chrono::steady_clock::now()).count();
        if(remaining<=0)break;
        long long wait_ns=(head!=completed || !pending.empty()) ? 60000 : remaining;
        const timespec timeout={wait_ns/1000000000,wait_ns%1000000000};
        int n=epoll_pwait2(ep,events,BF_LLM_SLOTS*2,&timeout,nullptr);
#else
        int n=epoll_wait(ep,events,BF_LLM_SLOTS*2,0);
#endif
        if(*stopped)break;
        if(n<0 && errno!=EINTR) { perror("epoll wait");break; }
        for(int e=0;e<n;e++) {
            int fd=events[e].data.fd;
            if(fd==wake) { uint64_t count;ssize_t ignored=read(wake,&count,sizeof(count));(void)ignored;continue; }
            if(fd==listener) {
                while(true) {
                    int child=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);
                    if(child<0) break;
                    auto peer=std::make_shared<Peer>();peer->fd=child;
                    peers[child]=peer;accepted++;
                    watch.events=EPOLLIN|EPOLLRDHUP;watch.data.fd=child;
                    if(epoll_ctl(ep,EPOLL_CTL_ADD,child,&watch)) disconnect(*peer);
                }
            } else {
                auto it=peers.find(fd);if(it==peers.end()) continue;
                Peer &peer=*it->second;
                char buffer[4096];
                while(peer.fd>=0) {
                    ssize_t got=recv(peer.fd,buffer,sizeof(buffer),MSG_DONTWAIT);
                    if(got>0) peer.input.append(buffer,got);
                    else {
                        if(got==0) {
                            peer.eof=true;epoll_ctl(ep,EPOLL_CTL_DEL,peer.fd,nullptr);
                        } else if(errno!=EAGAIN && errno!=EWOULDBLOCK && errno!=EINTR)
                            disconnect(peer);
                        break;
                    }
                }
                enqueue(it->second);
            }
        }
        for(unsigned i=0;i<BF_LLM_SLOTS;i++) {
            Reply &reply=replies[i];if(!reply.peer) continue;
            auto peer_ref=reply.peer;Peer &peer=*peer_ref;bf_llm_slot *slot=&page->llm[i];
            unsigned state=__atomic_load_n(&slot->state,__ATOMIC_ACQUIRE);
            unsigned short flags=__atomic_load_n(&slot->pad,__ATOMIC_ACQUIRE);
            bool rejected=flags&BF_LLM_REJECTED;
            if((flags&BF_LLM_VALIDATING) || (rejected && state!=BF_DONE)) continue;
            unsigned produced=__atomic_load_n(&slot->produced,__ATOMIC_ACQUIRE);
            if(state!=BF_DONE && produced==slot->n_gen && produced) produced--;
            if(rejected && (flags&BF_LLM_TRANSPORT_MASK)==1) disconnect(peer);
            if((flags&BF_LLM_TRANSPORT_MASK)==2 && reply.header.empty()) {
                reply.header="HTTP/1.1 "+std::string(rejected ? "400 Bad Request" : "200 OK")
                    +"\r\nContent-Type: application/octet-stream\r\nContent-Length: "
                    +std::to_string(rejected ? 0 : slot->n_gen*4)+"\r\n\r\n";
            }
            // Keep default TCP buffering; submit header and first tokens together.
            if(peer.fd>=0 && (produced || rejected))
                send_reply(peer,reply,slot,produced);
            if(state==BF_DONE && (peer.fd<0 ||
                (reply.header_sent==reply.header.size() && reply.bytes==produced*4))) {
                peer.slot=-1;reply={};
                __atomic_store_n(&slot->state,(unsigned)BF_FREE,__ATOMIC_RELEASE);
                __atomic_fetch_and(&page->llm_admission,~(1ULL<<(32+i)),__ATOMIC_RELEASE);
                completed++;if(rejected) rejected_count++;
                enqueue(peer_ref);
            }
        }
        for(auto it=peers.begin();it!=peers.end();) {
            auto peer=it->second;
            if(peer->slot<0 && (peer->fd<0 || (peer->eof && peer->input.empty()))) {
                disconnect(*peer);it=peers.erase(it);
            } else ++it;
        }
        while(!pending.empty()) {
            auto &request=pending.front();
            auto peer=request.peer;
            if(peer->fd<0) { peer->queued=false;pending.pop_front();continue; }
            unsigned i=head%BF_LLM_SLOTS;bf_llm_slot *slot=&page->llm[i];
            if(__atomic_load_n(&page->llm_reserved,__ATOMIC_ACQUIRE)&(1u<<i))break;
            __atomic_fetch_or(&page->llm_admission,1ULL<<(32+i),__ATOMIC_ACQ_REL);
            __atomic_store_n(&slot->state,(unsigned)BF_WRITING,__ATOMIC_RELEASE);
            slot->n_prompt=request.prompt;slot->n_gen=request.gen;slot->produced=0;
            slot->client_ns=request.client_ns;
            slot->pad=(request.http ? 2 : 1)|BF_LLM_VALIDATING;
            memcpy(slot->tok_in,peer->input.data()+request.offset+24,request.prompt*4);
            peer->input.erase(0,request.offset+request.bytes);
            replies[i].peer=peer;peer->slot=i;peer->queued=false;pending.pop_front();
            __atomic_store_n(&slot->state,(unsigned)BF_PENDING,__ATOMIC_RELEASE);
            __atomic_store_n(&page->llm_head,++head,__ATOMIC_RELEASE);
        }
    }
    for(auto &item:peers) disconnect(*item.second);
    user_wake_fd=-1;close(wake);close(ep);
    printf("USER_ADMISSION policy=eligible_frame_fifo queued_peak=%zu queued_at_stop=%zu\n",queued_peak,pending.size());
    printf("userspace TCP stopped: accepted=%u published=%u completed=%u rejected=%u\n",
           accepted,head,completed,rejected_count);fflush(stdout);
    return 0;
}

network_sources.bpf/include/bpfusion_queue.h:
/* SPDX-License-Identifier: Apache-2.0
 * BPFusion: canonical layout of the kernel<->GPU control page.
 *
 * Included by the eBPF ingress program, the resident GPU executor and the
 * gateway. POD only. The page is a single `BPF_MAP_TYPE_ARRAY` entry with
 * `BPF_F_MMAPABLE`, so the very same bytes are written by the BPF program in
 * softirq context and read/written by both userspace processes over the same
 * mapping.
 *
 * Ownership (one writer per field, no locks):
 *   slots[i].state    producer: FREE -> PENDING. GPU: PENDING -> FREE once the
 *                     request is in registers.
 *   done[i].state     executor: FREE -> DONE after done[i] is complete.
 *                     gateway:  DONE -> FREE once the response is on the wire.
 *   head              producer: requests published so far.
 *   done_seq          executor: futex word, bumped after each batch.
 *   published         executor: completions made visible (== head consumed).
 *   acked             gateway: responses sent (== completions consumed).
 *   ready             executor: 1 once calibrated and looping.
 *   drops             producer: requests that found the slot still busy.
 *
 * A slot is recyclable only when both `slots[i].state` and `done[i].state` are
 * FREE, so a completion cannot be overwritten before the gateway has sent it.
 *
 * The payload is exactly what the client sent: a 64-byte float vector plus its
 * own monotonic timestamp, echoed back in the response, so the client measures
 * a round trip without trusting server clocks.
 */
#ifndef BPFUSION_QUEUE_H
#define BPFUSION_QUEUE_H

#ifndef __VMLINUX_H__
typedef unsigned int __u32;
typedef unsigned long long __u64;
typedef unsigned short __u16;
#endif

#define BF_PORT 39400

/* LLM request ring: a second, independent slot ring that carries token ids
 * instead of a float vector. The BPF producer fills `tok_in` from the packet;
 * the resident model executor generates into `tok_out`, bumping `produced`
 * after each token so a client can measure TTFT (first token) and TPOT
 * (inter-token) over the same kernel->page path. */
#define BF_LLM_PORT 39402
#define BF_LLM_TCP_PORT 39403 /* same LLM ring, over stream TCP */
#define BF_LLM_MAGIC 0x514c4d51u /* 'Q','M','L','Q' little-endian */
#ifndef BF_LLM_SLOTS
#define BF_LLM_SLOTS 8
#endif
#define BF_LLM_MAX_TOK 64
/* Conservative peer buckets, not a connection/admission capacity limit. */
#define BF_PENDING_BUCKETS 4096
#define BF_LLM_TRANSPORT_MASK 3u
#define BF_LLM_VALIDATING 4u /* stream request awaits model-vocabulary check */
#define BF_LLM_REJECTED 8u /* executor rejected request before producing tokens */


#define BF_SLOTS 64
#define BF_MAX_BATCH 16
#define BF_VEC 16

/* Bootstrap correlation of kernel io_uring events with the model page. */
struct bf_uring_context {
    __u32 pid, pad;
    __u64 ring, nsdev, nsino;
};
/* io_uring registered-memory prefix used by its model-agnostic BPF loop. */
struct bf_uring_loop_control {
    __u32 sq_head, sq_tail, cq_tail;
    __u32 model_quiesced, finished, stop_requested;
    __u64 deadline_ns;
    __u32 cq_seen, timer_may_idle;
    __u64 now_ns;
    __u32 admission_seen, backlog_peak;
};
#define BF_IO_SEND_TAG 0xbff0ULL
#define BF_IO_ABORT_TAG 0xbff1ULL

/* CPU-owned admission backlog; model slots keep their existing layout. */
struct bf_llm_pending {
    __u32 n_prompt, n_gen, addr_be;
    __u16 port_be, flags;
    __u64 client_ns, ingress_ns;
    __u32 tokens[BF_LLM_MAX_TOK];
};

struct bf_llm_slot {
	__u32 state;      /* producer FREE->PENDING; executor ->DONE; TX ->FREE */
	__u32 n_gen;      /* tokens requested */
	__u32 n_prompt;   /* prompt tokens written to tok_in */
	__u32 produced;   /* tokens written to tok_out so far (executor) */
	__u32 addr_be;    /* client peer, network order */
	__u16 port_be;
	__u16 pad;       /* transport 1=TCP, 2=HTTP; producer VALIDATING, GPU status */
	__u64 client_ns;
	__u64 ingress_ns;
	__u64 gpu_done_ns;
	__u32 tok_in[BF_LLM_MAX_TOK];
	__u32 tok_out[BF_LLM_MAX_TOK];
};

/* Wire layout of a request datagram. */
#define BF_MAGIC 0x46504251u /* 'Q','B','P','F' little-endian */
struct bf_req_hdr {
	__u32 magic;
	__u32 pad;
	__u64 client_ns;
	float x[BF_VEC];
};

/* Wire layout of a response datagram. */
struct bf_resp_hdr {
	__u32 magic;
	__u32 id;
	__u32 pad;
	__u32 pad2;
	__u64 client_ns;  /* echoed from the request */
	__u64 ingress_ns; /* kernel parse time, CLOCK_MONOTONIC */
	__u64 gpu_start_ns;
	__u64 gpu_done_ns;
	float y[BF_VEC];
};

enum bf_state {
	BF_FREE = 0,
	BF_PENDING = 1,
	BF_DONE = 2,
	BF_WRITING = 3, /* producer reservation, before publishing PENDING */
};

struct bf_ctl_slot {
	__u32 state;
	__u32 id;
	__u64 client_ns;
	__u64 ingress_ns; /* bpf_ktime_get_ns() / CLOCK_MONOTONIC */
	float x[BF_VEC];
};

struct bf_done_slot {
	__u32 id;
	__u32 state;
	__u64 client_ns; /* copied from the request: the responder echoes it */
	__u64 ingress_ns;
	__u64 gpu_start_ns; /* %globaltimer */
	__u64 gpu_done_ns;  /* %globaltimer */
	float y[BF_VEC];
};

/* Where to send the answer, recorded by the producer for each slot. */
struct bf_peer {
	__u32 addr_be; /* IPv4, network order */
	__u16 port_be;
	__u16 pad2;
};
struct bf_page {
	__u32 head;
	__u32 done_seq;
	__u32 published;
	__u32 acked;
	__u32 drops;
	__u32 ready;
	__u32 n_slots;
	__u32 served;      /* completions published to done[] (GPU-owned) */
	__u32 pad0;
	__u64 stop_ns;     /* host CLOCK_MONOTONIC deadline for the resident
			    * kernel; 0 means "not set". */

	struct bf_ctl_slot slots[BF_SLOTS];
	struct bf_peer peers[BF_SLOTS];
	struct bf_done_slot done[BF_SLOTS];

	/* LLM request ring (see bf_llm_slot above). Kept at the tail so the
	 * MLP offsets are unchanged. */
	/* One CPU atomic reservation advances head and owns its physical slot.
	 * The high-word bit stays set until TX has finished all slot accesses;
	 * it protects wrap even if the producer has not published WRITING yet. */
	union {
		struct { __u32 llm_head, llm_reserved; };
		__u64 llm_admission;
	};
	struct bf_llm_slot llm[BF_LLM_SLOTS];
    __u32 llm_queued, admission_pad; /* CPU atomic count, read-only on GPU */
    __u32 llm_peer_pending[BF_PENDING_BUCKETS];
};

/* Network-order peer identity is identical in skb, slots and sockaddr_in.
 * Collisions retain another peer longer; they never permit an early close. */
#ifdef __CUDACC__
static __host__ __device__ __forceinline__
#else
static __inline__ __attribute__((always_inline))
#endif
__u32 bf_pending_bucket(__u32 addr_be, __u16 port_be)
{
    __u32 word=addr_be ^ (((__u32)port_be<<16)|port_be);
    word^=word>>16;word*=0x7feb352du;word^=word>>15;
    word*=0x846ca68bu;word^=word>>16;
    return word & (BF_PENDING_BUCKETS-1);
}

#define BF_PAGE_BYTES ((int)sizeof(struct bf_page))

/* A BPF_F_MMAPABLE array map exposes its value at offset 0 and the region is
 * the value size rounded up to a page multiple. Mapping only BF_PAGE_BYTES
 * (or a fixed two pages) is wrong: the layout grows with slot count and
 * transport metadata. A short mapping leaves fields outside the valid region. */
#define BF_PAGE_MMAP_BYTES \
	((long)((((long)BF_PAGE_BYTES + 4095L) / 4096L) * 4096L))

#endif /* BPFUSION_QUEUE_H */

